-- Detailed grammar theory for the 40 existing exercise topics.
insert into public.grammar_topics (
  id, language, level, title, overview_pt_br, formation_pt_br, use_cases,
  common_mistakes, notes_pt_br, sort_order
) values
('en-grammar-A1-1', 'en', 'A1', 'Verb to be', 'O verbo to be e a base do ingles, funcionando como ser ou estar. Diferente do portugues, onde temos dois verbos distintos, o ingles utiliza o mesmo termo para ambas as funcoes, o que exige atencao ao contexto para identificar o significado correto.

Ele e um verbo irregular e fundamental para descrever estados, identidades, profissoes e localizacoes. E o primeiro passo para construir frases simples e comunicar informacoes basicas sobre voce e o mundo ao seu redor.', 'Afirmativa: Sujeito + am/is/are + complemento (I am, You are, He/She/It is, We/They are). Negativa: Adiciona-se ''not'' apos o verbo (I am not, He is not/isn''t). Interrogativa: Inverte-se o sujeito com o verbo (Am I?, Is he?).', '[{"title_pt_br":"Identidade e Profissao","explanation_pt_br":"Usado para dizer quem voce e ou o que voce faz.","examples":[{"target":"I am a teacher.","translation_pt_br":"Eu sou professor."},{"target":"She is a doctor.","translation_pt_br":"Ela e medica."}]},{"title_pt_br":"Localizacao","explanation_pt_br":"Indica onde algo ou alguem esta.","examples":[{"target":"They are at home.","translation_pt_br":"Eles estao em casa."},{"target":"The book is on the table.","translation_pt_br":"O livro esta sobre a mesa."}]},{"title_pt_br":"Estados e Sentimentos","explanation_pt_br":"Descreve como alguem se sente ou caracteristicas fisicas.","examples":[{"target":"I am tired.","translation_pt_br":"Eu estou cansado."},{"target":"He is very happy.","translation_pt_br":"Ele esta muito feliz."}]}]'::jsonb, '[{"incorrect":"I happy.","correct":"I am happy.","explanation_pt_br":"Brasileiros tendem a omitir o verbo em frases simples, mas o ingles exige o verbo to be."},{"incorrect":"She are tall.","correct":"She is tall.","explanation_pt_br":"Confusao na conjugacao do verbo para a terceira pessoa do singular."},{"incorrect":"Are you teacher?","correct":"Are you a teacher?","explanation_pt_br":"Omissao do artigo indefinido antes de profissoes."}]'::jsonb, '["Use contraçoes (I''m, he''s, they''re) para soar mais natural na fala.","Lembre-se que ''it'' e usado para objetos e animais."]'::jsonb, 1),
('en-grammar-A1-2', 'en', 'A1', 'Articles and plurals', 'Os artigos (a, an, the) e os plurais sao essenciais para definir a quantidade e a especificidade dos substantivos. O ingles usa ''a'' antes de consoantes e ''an'' antes de sons de vogais, o que difere do portugues que varia em genero (o/a/um/uma).

Os plurais geralmente sao formados adicionando -s, mas existem irregularidades importantes. Dominar esses conceitos evita erros basicos de concordancia e clareza na comunicacao.', 'Artigos: ''A'' para sons consonantais, ''an'' para sons vocalicos, ''the'' para especificos. Plurais: Adiciona-se -s na maioria dos casos. Substantivos terminados em -s, -sh, -ch, -x recebem -es. Irregulares comuns: child/children, person/people.', '[{"title_pt_br":"Artigo Indefinido","explanation_pt_br":"Usado para algo nao especifico ou mencionado pela primeira vez.","examples":[{"target":"I have a car.","translation_pt_br":"Eu tenho um carro."},{"target":"She is an artist.","translation_pt_br":"Ela e uma artista."}]},{"title_pt_br":"Artigo Definido","explanation_pt_br":"Usado para algo especifico que o ouvinte ja conhece.","examples":[{"target":"The dog is barking.","translation_pt_br":"O cachorro esta latindo."}]},{"title_pt_br":"Plural Regular","explanation_pt_br":"A forma mais comum de indicar mais de um item.","examples":[{"target":"Two apples.","translation_pt_br":"Duas macas."},{"target":"Many boxes.","translation_pt_br":"Muitas caixas."}]}]'::jsonb, '[{"incorrect":"I have a apples.","correct":"I have apples.","explanation_pt_br":"Artigos indefinidos (a/an) nunca acompanham substantivos no plural."},{"incorrect":"She is a student good.","correct":"She is a good student.","explanation_pt_br":"Em ingles, o adjetivo vem antes do substantivo."},{"incorrect":"I have two childs.","correct":"I have two children.","explanation_pt_br":"Erro comum ao tentar aplicar a regra do -s em plurais irregulares."}]'::jsonb, '["O som da palavra determina ''a'' ou ''an'', nao a letra escrita (ex: an hour).","Substantivos incontaveis (water, money) nao vao para o plural."]'::jsonb, 2),
('en-grammar-A2-3', 'en', 'A2', 'Simple present', 'O Simple Present e usado para habitos, rotinas, fatos permanentes e verdades universais. E o tempo verbal mais frequente para descrever a vida cotidiana.

A principal diferenca para o portugues e a necessidade de adicionar -s, -es ou -ies ao verbo na terceira pessoa do singular (he, she, it), algo que nao existe na conjugacao do portugues.', 'Afirmativa: Verbo base (I/you/we/they) ou verbo + s/es (he/she/it). Negativa: Sujeito + do not/does not + verbo base. Interrogativa: Do/Does + sujeito + verbo base.', '[{"title_pt_br":"Habitos e Rotinas","explanation_pt_br":"Descreve acoes que acontecem com frequencia.","examples":[{"target":"I drink coffee every morning.","translation_pt_br":"Eu bebo cafe toda manha."},{"target":"She goes to the gym on Mondays.","translation_pt_br":"Ela vai a academia as segundas-feiras."}]},{"title_pt_br":"Fatos Permanentes","explanation_pt_br":"Situacoes que sao verdadeiras por um longo periodo.","examples":[{"target":"He lives in Sao Paulo.","translation_pt_br":"Ele mora em Sao Paulo."}]},{"title_pt_br":"Verdades Universais","explanation_pt_br":"Leis da natureza ou fatos cientificos.","examples":[{"target":"The sun rises in the east.","translation_pt_br":"O sol nasce no leste."}]}]'::jsonb, '[{"incorrect":"He drink coffee.","correct":"He drinks coffee.","explanation_pt_br":"Esquecimento do -s na terceira pessoa do singular."},{"incorrect":"Do she like pizza?","correct":"Does she like pizza?","explanation_pt_br":"Uso incorreto do auxiliar ''do'' para a terceira pessoa."},{"incorrect":"She doesn''t likes pizza.","correct":"She doesn''t like pizza.","explanation_pt_br":"O verbo volta a forma base quando o auxiliar ''does'' ja esta presente."}]'::jsonb, '["Verbos terminados em -o, -ch, -sh, -ss, -x recebem -es na 3a pessoa.","Verbos terminados em consoante + y perdem o y e ganham -ies."]'::jsonb, 3),
('en-grammar-A2-4', 'en', 'A2', 'Past simple', 'O Past Simple e usado para acoes que comecaram e terminaram em um tempo definido no passado. Diferente do portugues, que possui muitas conjugacoes para o passado, o ingles simplifica a estrutura, mas exige o aprendizado de verbos irregulares.

E fundamental para contar historias, relatar eventos passados e descrever experiencias concluidas.', 'Afirmativa: Verbo + -ed (regulares) ou forma irregular. Negativa: Sujeito + did not (didn''t) + verbo base. Interrogativa: Did + sujeito + verbo base.', '[{"title_pt_br":"Acoes concluidas","explanation_pt_br":"Eventos que ocorreram em um momento especifico.","examples":[{"target":"I visited my grandmother yesterday.","translation_pt_br":"Eu visitei minha avo ontem."},{"target":"They watched a movie last night.","translation_pt_br":"Eles assistiram a um filme ontem a noite."}]},{"title_pt_br":"Sequencia de eventos","explanation_pt_br":"Narrar uma serie de acoes passadas.","examples":[{"target":"I woke up, had breakfast, and went to work.","translation_pt_br":"Eu acordei, tomei cafe e fui trabalhar."}]}]'::jsonb, '[{"incorrect":"I did visited him.","correct":"I visited him.","explanation_pt_br":"Uso redundante do auxiliar ''did'' em frases afirmativas."},{"incorrect":"Did you went there?","correct":"Did you go there?","explanation_pt_br":"O verbo deve ficar na forma base apos o auxiliar ''did''."},{"incorrect":"I buyed a car.","correct":"I bought a car.","explanation_pt_br":"Tentativa de aplicar a regra do -ed em verbos irregulares."}]'::jsonb, '["O verbo ''to be'' no passado (was/were) nao usa o auxiliar ''did''.","Memorize os verbos irregulares mais comuns, pois eles nao seguem regras."]'::jsonb, 4),
('en-grammar-A2-5', 'en', 'A2', 'Future plans', 'Para expressar planos e intencoes futuras, o ingles utiliza principalmente o ''going to'' e o ''will''. O ''going to'' e usado para planos decididos ou evidencias claras, enquanto o ''will'' e usado para decisoes espontaneas ou promessas.

Entender essa diferenca e crucial para nao soar confuso ao falar de seus projetos futuros.', 'Going to: Sujeito + am/is/are + going to + verbo base. Will: Sujeito + will + verbo base. Negativa: Adiciona-se ''not'' apos o verbo to be ou o will.', '[{"title_pt_br":"Planos decididos","explanation_pt_br":"Algo que voce ja planejou fazer.","examples":[{"target":"I am going to travel to London next year.","translation_pt_br":"Eu vou viajar para Londres no proximo ano."}]},{"title_pt_br":"Decisoes espontaneas","explanation_pt_br":"Algo decidido no momento da fala.","examples":[{"target":"I will help you with that bag.","translation_pt_br":"Eu vou te ajudar com essa mala."}]}]'::jsonb, '[{"incorrect":"I go to travel tomorrow.","correct":"I am going to travel tomorrow.","explanation_pt_br":"Omissao do verbo to be antes de ''going to''."},{"incorrect":"I will to go.","correct":"I will go.","explanation_pt_br":"Adicao incorreta de ''to'' apos o modal ''will''."}]'::jsonb, '["Na fala informal, ''going to'' e frequentemente pronunciado como ''gonna''.","Use ''will'' para previsoes baseadas em opiniao."]'::jsonb, 5),
('en-grammar-B1-6', 'en', 'B1', 'Present perfect', 'O Present Perfect conecta o passado ao presente. Ele e usado para acoes que ocorreram em um tempo indefinido no passado ou que comecaram no passado e continuam ate agora. E um dos conceitos mais desafiadores para brasileiros, pois nao temos um equivalente direto.

O foco nao e quando algo aconteceu, mas sim a experiencia ou o resultado no presente.', 'Sujeito + have/has + participio passado do verbo. Negativa: have/has + not. Interrogativa: Have/Has + sujeito + participio.', '[{"title_pt_br":"Experiencia de vida","explanation_pt_br":"Falar sobre algo que voce ja fez, sem especificar quando.","examples":[{"target":"I have been to Japan.","translation_pt_br":"Eu ja estive no Japao."}]},{"title_pt_br":"Acoes continuas","explanation_pt_br":"Algo que comecou no passado e ainda ocorre.","examples":[{"target":"I have lived here for five years.","translation_pt_br":"Eu moro aqui ha cinco anos."}]}]'::jsonb, '[{"incorrect":"I have visited London yesterday.","correct":"I visited London yesterday.","explanation_pt_br":"Present Perfect nao pode ser usado com marcadores de tempo definidos (yesterday, last week)."},{"incorrect":"I live here since 2020.","correct":"I have lived here since 2020.","explanation_pt_br":"Brasileiros usam o presente, mas o ingles exige o Present Perfect para duracao."}]'::jsonb, '["Participle geralmente termina em -ed para regulares, mas ha muitos irregulares (gone, seen, done).","Use ''for'' para duracao e ''since'' para ponto de inicio."]'::jsonb, 6),
('en-grammar-B1-7', 'en', 'B1', 'Relative clauses', 'As oracoes relativas servem para dar informacoes extras sobre um substantivo sem precisar iniciar uma nova frase. Elas utilizam pronomes relativos como ''who'', ''which'', ''that'' e ''where''.

Elas tornam o texto mais fluido e sofisticado, permitindo conectar ideias de forma eficiente.', 'Substantivo + pronome relativo + oracao. ''Who'' para pessoas, ''which'' para coisas, ''that'' para ambos (em oracoes restritivas), ''where'' para lugares.', '[{"title_pt_br":"Definir pessoas","explanation_pt_br":"Identificar quem e a pessoa.","examples":[{"target":"The man who lives next door is a doctor.","translation_pt_br":"O homem que mora ao lado e medico."}]},{"title_pt_br":"Descrever coisas","explanation_pt_br":"Adicionar detalhes sobre objetos.","examples":[{"target":"The book that I read was great.","translation_pt_br":"O livro que eu li era otimo."}]}]'::jsonb, '[{"incorrect":"The house which I live is big.","correct":"The house where I live is big.","explanation_pt_br":"Uso incorreto de ''which'' para lugares; deve-se usar ''where''."},{"incorrect":"The person that he is my friend.","correct":"The person who is my friend.","explanation_pt_br":"Repeticao desnecessaria do sujeito dentro da oracao relativa."}]'::jsonb, '["Em oracoes restritivas, o pronome relativo pode ser omitido se nao for o sujeito da oracao.","Use virgulas para oracoes explicativas (nao restritivas)."]'::jsonb, 7),
('en-grammar-B1-8', 'en', 'B1', 'Modals and advice', 'Verbos modais como ''should'', ''must'', ''can'' e ''might'' alteram o sentido do verbo principal, indicando obrigacao, possibilidade ou conselho. Eles nao mudam na terceira pessoa e nao usam ''to'' (exceto ''have to'').

Sao fundamentais para expressar nuances de opiniao e necessidade.', 'Sujeito + modal + verbo base. Nunca variam (nao ganham -s).', '[{"title_pt_br":"Dar conselhos","explanation_pt_br":"Usar ''should'' para sugerir algo.","examples":[{"target":"You should study more.","translation_pt_br":"Voce deveria estudar mais."}]},{"title_pt_br":"Obrigacao","explanation_pt_br":"Usar ''must'' ou ''have to'' para necessidade.","examples":[{"target":"You must wear a seatbelt.","translation_pt_br":"Voce deve usar cinto de seguranca."}]}]'::jsonb, '[{"incorrect":"He shoulds go.","correct":"He should go.","explanation_pt_br":"Modais nunca recebem -s na terceira pessoa."},{"incorrect":"I can to swim.","correct":"I can swim.","explanation_pt_br":"O modal ''can'' e seguido diretamente pelo verbo, sem ''to''."}]'::jsonb, '["Must expressa obrigacao forte, should expressa recomendacao.","Could e a forma polida de pedir algo."]'::jsonb, 8),
('en-grammar-B2-9', 'en', 'B2', 'Conditionals', 'As condicionais (if-clauses) expressam situacoes hipoteticas ou reais. Existem quatro tipos principais (Zero, First, Second, Third), cada um com um nivel diferente de probabilidade.

Dominar as condicionais permite expressar planos complexos, arrependimentos e possibilidades futuras.', 'Zero: If + present, present. First: If + present, will. Second: If + past, would. Third: If + past perfect, would have + participle.', '[{"title_pt_br":"Primeira condicional","explanation_pt_br":"Possibilidades reais no futuro.","examples":[{"target":"If it rains, I will stay home.","translation_pt_br":"Se chover, eu ficarei em casa."}]},{"title_pt_br":"Segunda condicional","explanation_pt_br":"Situacoes hipoteticas ou improvaveis.","examples":[{"target":"If I won the lottery, I would travel the world.","translation_pt_br":"Se eu ganhasse na loteria, eu viajaria o mundo."}]}]'::jsonb, '[{"incorrect":"If I will go, I will call you.","correct":"If I go, I will call you.","explanation_pt_br":"Nao se usa ''will'' na oracao do ''if'' na primeira condicional."},{"incorrect":"If I would have money, I would buy it.","correct":"If I had money, I would buy it.","explanation_pt_br":"Uso incorreto do ''would'' na oracao do ''if''."}]'::jsonb, '["A ordem das oracoes pode ser invertida sem mudar o sentido.","Use ''were'' para todas as pessoas na segunda condicional (If I were you)."]'::jsonb, 9),
('en-grammar-B2-10', 'en', 'B2', 'Reported speech and nuance', 'O Reported Speech (discurso indireto) e usado para relatar o que outra pessoa disse. A regra principal e o ''backshift'' (recuo do tempo verbal), onde o tempo original volta um passo para o passado.

E essencial para narrar conversas e transmitir informacoes de terceiros com precisao.', 'Verbo de elocucao (said/told) + que (opcional) + oracao com tempo verbal recuado. Ex: Present vira Past, Past vira Past Perfect.', '[{"title_pt_br":"Relatar fatos","explanation_pt_br":"Contar o que alguem disse anteriormente.","examples":[{"target":"He said he was tired.","translation_pt_br":"Ele disse que estava cansado."}]},{"title_pt_br":"Relatar perguntas","explanation_pt_br":"Transformar perguntas diretas em indiretas.","examples":[{"target":"She asked where I lived.","translation_pt_br":"Ela perguntou onde eu morava."}]}]'::jsonb, '[{"incorrect":"He said me that he was happy.","correct":"He told me that he was happy.","explanation_pt_br":"O verbo ''said'' nao aceita objeto indireto (me, her); use ''told''."},{"incorrect":"She asked me where do I live.","correct":"She asked me where I lived.","explanation_pt_br":"Em perguntas indiretas, a ordem e sujeito-verbo, nao interrogativa."}]'::jsonb, '["Pronomes e marcadores de tempo tambem mudam (now vira then, here vira there).","Se o fato ainda for verdadeiro, o recuo do tempo e opcional."]'::jsonb, 10),
('es-grammar-A1-1', 'es', 'A1', 'Ser y estar', 'A distinção entre ser e estar é o primeiro grande desafio para brasileiros. Enquanto o português usa ambos de forma similar, o espanhol exige que o falante identifique se a característica é intrínseca (ser) ou um estado passageiro/localização (estar).', 'Ser: soy, eres, es, somos, sois, son. Estar: estoy, estás, está, estamos, estáis, están. A negativa é feita com ''no'' antes do verbo. A interrogativa inverte a ordem ou mantém a ordem direta com entonação ascendente.', '[{"title_pt_br":"Identidade e Profissão","explanation_pt_br":"Usamos ser para definir quem alguém é ou o que faz.","examples":[{"target":"Yo soy profesor.","translation_pt_br":"Eu sou professor."},{"target":"Ella es María.","translation_pt_br":"Ela é a Maria."}]},{"title_pt_br":"Localização","explanation_pt_br":"Usamos estar para indicar onde algo ou alguém está localizado.","examples":[{"target":"Madrid está en España.","translation_pt_br":"Madri fica na Espanha."},{"target":"Nosotros estamos en casa.","translation_pt_br":"Nós estamos em casa."}]},{"title_pt_br":"Estados temporários","explanation_pt_br":"Usamos estar para condições de saúde ou humor.","examples":[{"target":"Hoy estoy cansado.","translation_pt_br":"Hoje estou cansado."}]}]'::jsonb, '[{"incorrect":"Estoy brasileño.","correct":"Soy brasileño.","explanation_pt_br":"Nacionalidade é uma característica permanente, logo usa-se ser."},{"incorrect":"La fiesta es en mi casa.","correct":"La fiesta es en mi casa.","explanation_pt_br":"Atenção: eventos acontecem (ser), mas pessoas estão (estar). O erro comum é confundir localização de coisas com eventos."},{"incorrect":"Él está alto.","correct":"Él es alto.","explanation_pt_br":"Altura é uma característica física permanente, usa-se ser."}]'::jsonb, '["Lembre-se: Ser = Essência/Identidade; Estar = Estado/Localização.","A localização de eventos (festas, reuniões) sempre utiliza o verbo ser."]'::jsonb, 1),
('es-grammar-A1-2', 'es', 'A1', 'Género y número', 'O gênero e o número em espanhol seguem regras parecidas com o português, mas com falsos amigos importantes. A maioria das palavras terminadas em ''o'' são masculinas e em ''a'' são femininas, mas há exceções cruciais.', 'Para o plural, adiciona-se ''s'' se terminar em vogal e ''es'' se terminar em consoante. O gênero é determinado pelo artigo (el/la) ou pela terminação da palavra.', '[{"title_pt_br":"Substantivos terminados em vogal","explanation_pt_br":"Regra geral para pluralizar.","examples":[{"target":"El libro / Los libros","translation_pt_br":"O livro / Os livros"}]},{"title_pt_br":"Substantivos terminados em consoante","explanation_pt_br":"Adiciona-se ''es'' para o plural.","examples":[{"target":"El profesor / Los profesores","translation_pt_br":"O professor / Os professores"}]}]'::jsonb, '[{"incorrect":"La problema","correct":"El problema","explanation_pt_br":"Palavras terminadas em -ma de origem grega costumam ser masculinas."},{"incorrect":"La viaje","correct":"El viaje","explanation_pt_br":"Viagem é masculino em espanhol."},{"incorrect":"La sangre","correct":"La sangre","explanation_pt_br":"O gênero pode variar entre português e espanhol, sempre verifique o dicionário."}]'::jsonb, '["A maioria das palavras terminadas em -aje são masculinas.","Palavras terminadas em -ción ou -sión são quase sempre femininas."]'::jsonb, 2),
('es-grammar-A2-3', 'es', 'A2', 'Presente regular', 'O presente do indicativo é usado para ações habituais, verdades universais e planos imediatos. A estrutura é dividida em três conjugações: -ar, -er e -ir.', 'Verbos -ar: o, as, a, amos, áis, an. Verbos -er: o, es, e, emos, éis, en. Verbos -ir: o, es, e, imos, ís, en.', '[{"title_pt_br":"Rotina","explanation_pt_br":"Descrever hábitos diários.","examples":[{"target":"Yo como a las dos.","translation_pt_br":"Eu como às duas."}]},{"title_pt_br":"Verdades universais","explanation_pt_br":"Fatos que não mudam.","examples":[{"target":"El sol sale por el este.","translation_pt_br":"O sol nasce no leste."}]}]'::jsonb, '[{"incorrect":"Yo como mucho","correct":"Yo como mucho","explanation_pt_br":"Brasileiros tendem a omitir o pronome, o que é correto, mas a conjugação deve ser precisa."},{"incorrect":"Ellos habla","correct":"Ellos hablan","explanation_pt_br":"Erro de concordância número-pessoal."},{"incorrect":"Nosotros comemos","correct":"Nosotros comemos","explanation_pt_br":"Atenção à terminação -emos vs -imos."}]'::jsonb, '["O ''vosotros'' é usado apenas na Espanha.","Muitos verbos sofrem ditongação (e>ie, o>ue) na raiz."]'::jsonb, 3),
('es-grammar-A2-4', 'es', 'A2', 'Pretérito indefinido', 'O pretérito indefinido (ou perfeito simples) é usado para ações concluídas em um tempo determinado no passado. É o tempo da narração de eventos pontuais.', 'Verbos -ar: é, aste, ó, amos, asteis, aron. Verbos -er/-ir: í, iste, ió, imos, isteis, ieron.', '[{"title_pt_br":"Ações pontuais","explanation_pt_br":"Eventos que ocorreram uma vez.","examples":[{"target":"Ayer compré un libro.","translation_pt_br":"Ontem comprei um livro."}]},{"title_pt_br":"Sequência de eventos","explanation_pt_br":"Narrar uma série de ações passadas.","examples":[{"target":"Llegué, vi y vencí.","translation_pt_br":"Cheguei, vi e venci."}]}]'::jsonb, '[{"incorrect":"Yo comi","correct":"Yo comí","explanation_pt_br":"A acentuação é obrigatória na primeira pessoa do singular."},{"incorrect":"Ellos hablaron","correct":"Ellos hablaron","explanation_pt_br":"Atenção ao som do ''r'' final."},{"incorrect":"Yo fui a comer","correct":"Yo fui a comer","explanation_pt_br":"O verbo ir no indefinido é irregular (fui, fuiste, fue...)."}]'::jsonb, '["Muitos verbos são irregulares neste tempo (tener -> tuve, hacer -> hice).","É o tempo narrativo por excelência."]'::jsonb, 4),
('es-grammar-A2-5', 'es', 'A2', 'Futuro y planes', 'Para falar de futuro, o espanhol utiliza frequentemente a perífrase ''ir + a + infinitivo'' para planos próximos, ou o futuro simples para intenções mais distantes.', 'Ir + a + infinitivo: vou, vas, va, vamos, vais, van + a + verbo. Futuro simples: infinitivo + é, ás, á, emos, éis, án.', '[{"title_pt_br":"Planos imediatos","explanation_pt_br":"Usar ir + a para intenções próximas.","examples":[{"target":"Voy a estudiar mañana.","translation_pt_br":"Vou estudar amanhã."}]},{"title_pt_br":"Previsões","explanation_pt_br":"Usar o futuro simples para suposições.","examples":[{"target":"Mañana hará calor.","translation_pt_br":"Amanhã fará calor."}]}]'::jsonb, '[{"incorrect":"Voy estudiar","correct":"Voy a estudiar","explanation_pt_br":"A preposição ''a'' é obrigatória na perífrase."},{"incorrect":"Yo iré a comer","correct":"Yo voy a comer","explanation_pt_br":"Para planos, a forma perifrástica é muito mais natural que o futuro simples."},{"incorrect":"Mañana llueve","correct":"Mañana lloverá","explanation_pt_br":"Para previsões, o futuro simples é preferível."}]'::jsonb, '["A perífrase ''ir + a'' é muito mais comum na fala cotidiana que o futuro simples.","O futuro simples é usado para incerteza ou probabilidade no presente."]'::jsonb, 5),
('es-grammar-B1-6', 'es', 'B1', 'Pretérito perfecto', 'O pretérito perfecto (composto) é usado para ações passadas que têm relação com o presente ou que ocorreram em um tempo não terminado (hoje, esta semana).', 'Verbo auxiliar ''haber'' (he, has, ha, hemos, habéis, han) + particípio (ado/ido).', '[{"title_pt_br":"Tempo não terminado","explanation_pt_br":"Ações ocorridas hoje ou este mês.","examples":[{"target":"Hoy he trabajado mucho.","translation_pt_br":"Hoje trabalhei muito."}]},{"title_pt_br":"Experiência de vida","explanation_pt_br":"Perguntar sobre experiências sem tempo definido.","examples":[{"target":"¿Has viajado a España?","translation_pt_br":"Você já viajou para a Espanha?"}]}]'::jsonb, '[{"incorrect":"He comido ayer","correct":"Comí ayer","explanation_pt_br":"Não se usa pretérito perfeito com marcadores de tempo encerrado (ayer, el año pasado)."},{"incorrect":"Yo tengo comido","correct":"He comido","explanation_pt_br":"O auxiliar é ''haber'', nunca ''tener''."},{"incorrect":"Has ido?","correct":"¿Has ido?","explanation_pt_br":"Não esqueça a pontuação de interrogação inicial."}]'::jsonb, '["Existem muitos particípios irregulares (escrito, dicho, hecho, visto).","Na América Latina, usa-se o indefinido onde na Espanha se usaria o perfeito."]'::jsonb, 6),
('es-grammar-B1-7', 'es', 'B1', 'Pronombres de objeto', 'Os pronomes de objeto direto (OD) e indireto (OI) substituem substantivos para evitar repetição. O OD responde ''o quê?'' e o OI responde ''a quem?''.', 'OD: me, te, lo/la, nos, os, los/las. OI: me, te, le, nos, os, les. O pronome vem antes do verbo conjugado ou colado ao infinitivo/gerúndio.', '[{"title_pt_br":"Substituição de OD","explanation_pt_br":"Evitar repetir o objeto direto.","examples":[{"target":"Compro el pan -> Lo compro.","translation_pt_br":"Compro o pão -> Eu o compro."}]},{"title_pt_br":"Substituição de OI","explanation_pt_br":"Indicar o destinatário da ação.","examples":[{"target":"Digo la verdad a Juan -> Le digo la verdad.","translation_pt_br":"Digo a verdade a João -> Digo-lhe a verdade."}]}]'::jsonb, '[{"incorrect":"Lo digo a él","correct":"Le digo a él","explanation_pt_br":"O objeto indireto (a quem) exige o pronome ''le'', não ''lo''."},{"incorrect":"Dámelo a mí","correct":"Dámelo a mí","explanation_pt_br":"A ordem dos pronomes (OI + OD) é fixa."},{"incorrect":"Le vi en la calle","correct":"Lo vi en la calle","explanation_pt_br":"Ver alguém é objeto direto (lo/la), não indireto."}]'::jsonb, '["Leísmo: na Espanha, usa-se ''le'' para pessoas do sexo masculino como objeto direto.","Se houver dois pronomes começando com ''l'' (le lo), o primeiro vira ''se''."]'::jsonb, 7),
('es-grammar-B1-8', 'es', 'B1', 'Subjuntivo presente', 'O subjuntivo expressa subjetividade, desejos, dúvidas ou negações. É o modo da incerteza, contrastando com o indicativo, que é o modo da realidade.', 'Troca-se a vogal temática: verbos -ar usam ''e'', verbos -er/-ir usam ''a''. Ex: hablar -> hable, comer -> coma.', '[{"title_pt_br":"Desejos e vontades","explanation_pt_br":"Expressar o que queremos que outros façam.","examples":[{"target":"Quiero que vengas.","translation_pt_br":"Quero que você venha."}]},{"title_pt_br":"Dúvida e negação","explanation_pt_br":"Expressar incerteza.","examples":[{"target":"No creo que sea verdad.","translation_pt_br":"Não creio que seja verdade."}]}]'::jsonb, '[{"incorrect":"Espero que vienes","correct":"Espero que vengas","explanation_pt_br":"Após ''espero que'' é obrigatório o uso do subjuntivo."},{"incorrect":"Quiero que él habla","correct":"Quiero que él hable","explanation_pt_br":"Erro na troca da vogal temática."},{"incorrect":"Es verdad que sea así","correct":"Es verdad que es así","explanation_pt_br":"Expressões de certeza absoluta pedem indicativo."}]'::jsonb, '["O gatilho para o subjuntivo é quase sempre uma mudança de sujeito entre a oração principal e a subordinada.","A conjunção ''que'' é o conector obrigatório."]'::jsonb, 8),
('es-grammar-B2-9', 'es', 'B2', 'Condicionales', 'As orações condicionais (frases com ''si'') estabelecem uma relação de causa e efeito. No nível B2, focamos nas condições hipotéticas e irreais.', 'Condicional simples: infinitivo + ía, ías, ía, íamos, íais, ían. Condicional composto: habría + particípio.', '[{"title_pt_br":"Hipótese provável","explanation_pt_br":"Se + presente, futuro/imperativo.","examples":[{"target":"Si llueve, no iré.","translation_pt_br":"Se chover, não irei."}]},{"title_pt_br":"Hipótese improvável","explanation_pt_br":"Si + imperfeito do subjuntivo, condicional.","examples":[{"target":"Si tuviera dinero, viajaría.","translation_pt_br":"Se eu tivesse dinheiro, viajaria."}]}]'::jsonb, '[{"incorrect":"Si tendría dinero, compraría","correct":"Si tuviera dinero, compraría","explanation_pt_br":"Nunca se usa o condicional na oração com ''si''."},{"incorrect":"Si tengo dinero, compraría","correct":"Si tengo dinero, compraré","explanation_pt_br":"A concordância temporal deve ser respeitada."},{"incorrect":"Si fuera rico, viajara","correct":"Si fuera rico, viajaría","explanation_pt_br":"A oração principal da condição improvável pede condicional."}]'::jsonb, '["O imperfeito do subjuntivo (tuviera/tuviese) é essencial para o B2.","O condicional também é usado para polidez (¿Podrías ayudarme?)."]'::jsonb, 9),
('es-grammar-B2-10', 'es', 'B2', 'Discurso referido y matiz', 'O discurso referido (indireto) é a técnica de relatar o que outra pessoa disse. Exige ajustes de tempos verbais, pronomes e marcadores temporais.', 'Verbo de elocução (decir, afirmar) + que + oração subordinada. O tempo verbal costuma ''voltar'' um passo no passado.', '[{"title_pt_br":"Relato de declarações","explanation_pt_br":"Transformar fala direta em indireta.","examples":[{"target":"Dijo que vendría mañana.","translation_pt_br":"Ele disse que viria amanhã."}]},{"title_pt_br":"Mudança de marcadores","explanation_pt_br":"Ajustar ''hoy'' para ''aquel día'', etc.","examples":[{"target":"Dijo que estaba cansado ese día.","translation_pt_br":"Ele disse que estava cansado naquele dia."}]}]'::jsonb, '[{"incorrect":"Dijo que vendrá","correct":"Dijo que vendría","explanation_pt_br":"Se o verbo principal está no passado, a subordinada deve seguir a concordância."},{"incorrect":"Me dijo que yo voy","correct":"Me dijo que yo iba","explanation_pt_br":"Ajuste de tempo verbal é obrigatório no discurso indireto."},{"incorrect":"Él dijo: que vendría","correct":"Él dijo que vendría","explanation_pt_br":"Não se usa dois pontos antes de ''que'' no discurso indireto."}]'::jsonb, '["O uso de verbos como ''preguntar'' exige ''si'' ou pronomes interrogativos.","O contexto determina o nível de formalidade do relato."]'::jsonb, 10),
('fr-grammar-A1-1', 'fr', 'A1', 'Être et avoir', 'Os verbos etre (ser/estar) e avoir (ter) são os pilares da língua francesa. Enquanto etre é usado para estados permanentes ou temporários e identificação, avoir é usado para posse e estados físicos ou psicológicos. Diferente do português, onde usamos ter para idade, no francês o uso do avoir é obrigatório.

Eles também funcionam como auxiliares para a formação de tempos compostos. Dominar esses verbos desde o início é essencial, pois eles aparecem em quase todas as frases do cotidiano.', 'Afirmativa: Je suis/ai, Tu es/as, Il-Elle-On est/a, Nous sommes/avons, Vous êtes/avez, Ils-Elles sont/ont. Negativa: Adiciona-se ne/n'' antes do verbo e pas depois (Je ne suis pas). Interrogativa: Inversão (Est-il?), uso de est-ce que (Est-ce qu''il est?) ou entonação ascendente.', '[{"title_pt_br":"Identidade e Profissão","explanation_pt_br":"Usamos etre para definir quem somos ou o que fazemos.","examples":[{"target":"Je suis brésilien.","translation_pt_br":"Eu sou brasileiro."},{"target":"Elle est médecin.","translation_pt_br":"Ela é médica."}]},{"title_pt_br":"Posse e Idade","explanation_pt_br":"Usamos avoir para indicar o que possuímos ou quantos anos temos.","examples":[{"target":"J''ai une voiture.","translation_pt_br":"Eu tenho um carro."},{"target":"Il a vingt ans.","translation_pt_br":"Ele tem vinte anos."}]}]'::jsonb, '[{"incorrect":"J''ai 20 ans.","correct":"J''ai vingt ans.","explanation_pt_br":"Embora o uso do número seja aceito, em contextos formais prefere-se escrever por extenso."},{"incorrect":"Je suis faim.","correct":"J''ai faim.","explanation_pt_br":"Em francês, fome é algo que se tem, não algo que se é."},{"incorrect":"Il est un étudiant.","correct":"Il est étudiant.","explanation_pt_br":"Ao indicar profissão ou nacionalidade com etre, não se usa artigo indefinido."}]'::jsonb, '["A pronúncia de ''est'' (verbo) e ''et'' (conjunção) é idêntica.","A liaison é obrigatória em ''nous sommes'' e ''vous êtes''."]'::jsonb, 1),
('fr-grammar-A1-2', 'fr', 'A1', 'Articles et accord', 'Os artigos franceses (le, la, les, un, une, des) concordam em gênero e número com o substantivo. Diferente do português, o francês exige que quase todos os substantivos sejam acompanhados por um artigo ou determinante.

A concordância é fundamental: adjetivos mudam de forma conforme o gênero (masculino/feminino) e número (singular/plural) do substantivo que acompanham.', 'Artigos definidos: le (masc.), la (fem.), l'' (vogal), les (pl.). Artigos indefinidos: un (masc.), une (fem.), des (pl.). Adjetivos: geralmente adiciona-se ''e'' para feminino e ''s'' para plural.', '[{"title_pt_br":"Definição de objetos","explanation_pt_br":"Uso de artigos definidos para algo específico.","examples":[{"target":"Le livre est sur la table.","translation_pt_br":"O livro está sobre a mesa."}]},{"title_pt_br":"Indicação de quantidade indefinida","explanation_pt_br":"Uso de artigos indefinidos para algo não específico.","examples":[{"target":"J''ai une pomme.","translation_pt_br":"Eu tenho uma maçã."}]}]'::jsonb, '[{"incorrect":"La table est grand.","correct":"La table est grande.","explanation_pt_br":"O adjetivo deve concordar com o gênero do substantivo (table é feminino)."},{"incorrect":"J''aime le café.","correct":"J''aime le café.","explanation_pt_br":"Brasileiros costumam esquecer o artigo com verbos de preferência."},{"incorrect":"Il y a des hommes.","correct":"Il y a des hommes.","explanation_pt_br":"O ''s'' final de ''des'' deve ser pronunciado com liaison antes de vogal."}]'::jsonb, '["A maioria das palavras terminadas em ''e'' são femininas, mas há exceções.","O plural de ''un'' e ''une'' é sempre ''des''."]'::jsonb, 2),
('fr-grammar-A2-3', 'fr', 'A2', 'Le présent', 'O presente do indicativo em francês é usado para ações habituais, verdades universais e ações que ocorrem no momento da fala. É o tempo verbal mais versátil e frequente.

Os verbos são divididos em três grupos principais, sendo o primeiro grupo (-er) o mais regular e produtivo, enquanto o segundo (-ir) e o terceiro (irregulares) exigem memorização específica.', '1º grupo (-er): -e, -es, -e, -ons, -ez, -ent. 2º grupo (-ir): -is, -is, -it, -issons, -issez, -issent. 3º grupo: terminações variadas (-s, -s, -t, -ons, -ez, -ent ou -x, -x, -t, -ons, -ez, -ent).', '[{"title_pt_br":"Rotina","explanation_pt_br":"Descrever hábitos diários.","examples":[{"target":"Je mange à midi.","translation_pt_br":"Eu almoço ao meio-dia."}]},{"title_pt_br":"Verdades gerais","explanation_pt_br":"Fatos que são sempre verdadeiros.","examples":[{"target":"La terre tourne.","translation_pt_br":"A terra gira."}]}]'::jsonb, '[{"incorrect":"Je suis mangeant.","correct":"Je mange.","explanation_pt_br":"O francês não usa o gerúndio para o presente contínuo como o inglês ou português."},{"incorrect":"Ils finissent.","correct":"Ils finissent.","explanation_pt_br":"O ''ent'' final dos verbos não é pronunciado."},{"incorrect":"Je prends le bus.","correct":"Je prends le bus.","explanation_pt_br":"Confusão na conjugação de verbos irregulares como prendre."}]'::jsonb, '["Verbos como ''aller'' são irregulares, mas essenciais.","A terminação -ent é sempre muda."]'::jsonb, 3),
('fr-grammar-A2-4', 'fr', 'A2', 'Le passé composé', 'O passé composé é o tempo passado mais comum para descrever ações pontuais e concluídas no passado. Ele é composto por um verbo auxiliar (etre ou avoir) conjugado no presente + o particípio passado do verbo principal.

A escolha do auxiliar é crucial: a maioria dos verbos usa ''avoir'', enquanto verbos de movimento e mudança de estado usam ''etre'', exigindo concordância do particípio.', 'Auxiliar (avoir/etre) + Particípio Passado. Ex: J''ai mangé, Je suis allé(e). Verbos com ''etre'' concordam em gênero e número com o sujeito.', '[{"title_pt_br":"Ações pontuais","explanation_pt_br":"Eventos que aconteceram uma vez.","examples":[{"target":"J''ai acheté un livre.","translation_pt_br":"Eu comprei um livro."}]},{"title_pt_br":"Mudança de estado","explanation_pt_br":"Ações com verbos de movimento.","examples":[{"target":"Elle est partie hier.","translation_pt_br":"Ela partiu ontem."}]}]'::jsonb, '[{"incorrect":"J''ai allé.","correct":"Je suis allé.","explanation_pt_br":"Verbos de movimento usam o auxiliar ''etre''."},{"incorrect":"Elle est allé.","correct":"Elle est allée.","explanation_pt_br":"Falta de concordância do particípio com o sujeito feminino."},{"incorrect":"J''ai mangé le pomme.","correct":"J''ai mangé la pomme.","explanation_pt_br":"Erro de gênero no artigo após o verbo."}]'::jsonb, '["Memorize a ''Maison d''Etre'' para verbos que usam o auxiliar etre.","Particípios irregulares como ''fait'', ''dit'', ''pris'' devem ser memorizados."]'::jsonb, 4),
('fr-grammar-A2-5', 'fr', 'A2', 'Futur et projets', 'Para falar do futuro, o francês utiliza principalmente o ''futur proche'' (futuro próximo) para planos imediatos e o ''futur simple'' para planos mais distantes ou formais.

O futur proche é extremamente comum na fala cotidiana e é formado pelo verbo ''aller'' no presente + infinitivo do verbo principal.', 'Futur proche: Aller (présent) + infinitivo. Futur simple: Infinitivo + terminações (-ai, -as, -a, -ons, -ez, -ont).', '[{"title_pt_br":"Planos imediatos","explanation_pt_br":"Algo que você vai fazer em breve.","examples":[{"target":"Je vais manger.","translation_pt_br":"Eu vou comer."}]},{"title_pt_br":"Previsões","explanation_pt_br":"Algo que ocorrerá no futuro distante.","examples":[{"target":"Il fera beau demain.","translation_pt_br":"Fará bom tempo amanhã."}]}]'::jsonb, '[{"incorrect":"Je vais à manger.","correct":"Je vais manger.","explanation_pt_br":"Não se usa a preposição ''à'' entre o verbo aller e o infinitivo."},{"incorrect":"Je mangerai demain.","correct":"Je mangerai demain.","explanation_pt_br":"Confusão entre a terminação ''ai'' (futuro) e ''ais'' (condicional)."},{"incorrect":"Nous allons partirons.","correct":"Nous allons partir.","explanation_pt_br":"Mistura indevida de estruturas de futuro."}]'::jsonb, '["O futur proche é muito mais usado que o futur simple na conversação.","Verbos terminados em -re perdem o ''e'' final antes de adicionar as terminações do futur simple."]'::jsonb, 5),
('fr-grammar-B1-6', 'fr', 'B1', 'Imparfait ou passé composé', 'A distinção entre imparfait e passé composé é um dos maiores desafios para brasileiros. O passé composé foca na ação concluída, no evento que interrompe ou no fato pontual. O imparfait foca no contexto, na descrição, no hábito ou no estado mental/físico contínuo no passado.

Imagine o imparfait como o cenário de um filme e o passé composé como os eventos que acontecem dentro desse cenário.', 'Imparfait: Radical da 1ª pessoa do plural (nous) + terminações (-ais, -ais, -ait, -ions, -iez, -aient). Passé composé: Auxiliar + particípio.', '[{"title_pt_br":"Descrição de cenário","explanation_pt_br":"Descrever como as coisas eram.","examples":[{"target":"Il faisait beau.","translation_pt_br":"Estava fazendo bom tempo."}]},{"title_pt_br":"Ação interrompida","explanation_pt_br":"Uma ação contínua interrompida por outra.","examples":[{"target":"Je dormais quand il est arrivé.","translation_pt_br":"Eu dormia quando ele chegou."}]}]'::jsonb, '[{"incorrect":"J''ai été fatigué.","correct":"J''étais fatigué.","explanation_pt_br":"Estados físicos contínuos no passado pedem imparfait."},{"incorrect":"Chaque jour, j''ai mangé.","correct":"Chaque jour, je mangeais.","explanation_pt_br":"Hábitos no passado devem ser expressos no imparfait."},{"incorrect":"Il a pleuvait.","correct":"Il pleuvait.","explanation_pt_br":"Verbos meteorológicos são quase sempre usados no imparfait para descrever o tempo."}]'::jsonb, '["O verbo ''etre'' no imparfait é ''étais''.","Use imparfait para ''queria'', ''gostava'', ''pensava''."]'::jsonb, 6),
('fr-grammar-B1-7', 'fr', 'B1', 'Pronoms compléments', 'Os pronomes complementos (COD e COI) servem para evitar a repetição de substantivos. O COD (complément d''objet direct) substitui objetos diretos (le, la, les), enquanto o COI (complément d''objet indirect) substitui objetos regidos pela preposição ''à'' (lui, leur).

A posição desses pronomes é sempre antes do verbo conjugado, o que exige uma mudança de estrutura em relação ao português.', 'COD: le, la, les. COI: lui, leur. Posição: Sujeito + pronome + verbo. Em tempos compostos: Sujeito + pronome + auxiliar + particípio.', '[{"title_pt_br":"Substituição de objeto direto","explanation_pt_br":"Evitar repetir o nome de um objeto.","examples":[{"target":"Je le vois.","translation_pt_br":"Eu o vejo."}]},{"title_pt_br":"Substituição de pessoa (COI)","explanation_pt_br":"Substituir alguém que recebe uma ação.","examples":[{"target":"Je lui parle.","translation_pt_br":"Eu falo com ele/ela."}]}]'::jsonb, '[{"incorrect":"Je vois lui.","correct":"Je le vois.","explanation_pt_br":"O pronome complemento deve vir antes do verbo."},{"incorrect":"Je téléphone à lui.","correct":"Je lui téléphone.","explanation_pt_br":"Com verbos que pedem ''à'', usamos o pronome COI."},{"incorrect":"Je l''ai vu lui.","correct":"Je l''ai vu.","explanation_pt_br":"Não se deve repetir o objeto se o pronome já foi usado."}]'::jsonb, '["Lembre-se da ordem: me, te, se, nous, vous, le, la, les, lui, leur, y, en.","O pronome ''en'' substitui quantidades ou coisas precedidas de ''de''."]'::jsonb, 7),
('fr-grammar-B1-8', 'fr', 'B1', 'Le subjonctif', 'O subjonctivo francês expressa subjetividade, desejo, dúvida, necessidade ou emoção. Ele é usado em frases subordinadas introduzidas por ''que'', onde o sujeito da primeira oração é diferente do sujeito da segunda.

É um modo que exige atenção, pois muitas vezes o português usa o infinitivo onde o francês exige o subjonctivo.', 'Radical da 3ª pessoa do plural (ils) do presente + terminações (-e, -es, -e, -ions, -iez, -ent). Muitos verbos são irregulares (ex: aller, faire, avoir, etre).', '[{"title_pt_br":"Expressão de desejo","explanation_pt_br":"Quando queremos que alguém faça algo.","examples":[{"target":"Je veux que tu viennes.","translation_pt_br":"Eu quero que você venha."}]},{"title_pt_br":"Expressão de obrigação","explanation_pt_br":"Necessidade subjetiva.","examples":[{"target":"Il faut que nous partions.","translation_pt_br":"É preciso que nós partamos."}]}]'::jsonb, '[{"incorrect":"Je veux que tu viens.","correct":"Je veux que tu viennes.","explanation_pt_br":"Após ''que'' com verbos de desejo, o subjonctivo é obrigatório."},{"incorrect":"Je pense qu''il soit là.","correct":"Je pense qu''il est là.","explanation_pt_br":"Verbos de opinião (penser, croire) na afirmativa usam indicativo, não subjonctivo."},{"incorrect":"Il faut de partir.","correct":"Il faut partir.","explanation_pt_br":"Se não houver mudança de sujeito, usa-se o infinitivo."}]'::jsonb, '["A maioria dos verbos regulares no subjonctivo tem a mesma pronúncia para as três pessoas do singular e a 3ª do plural.","Memorize os irregulares: ''sois'', ''aies'', ''aies'', ''fasse'', ''aille''."]'::jsonb, 8),
('fr-grammar-B2-9', 'fr', 'B2', 'Les hypothèses', 'As hipóteses em francês são estruturadas com a conjunção ''si''. Existem três tipos principais: a condição real (presente + presente/futuro), a condição hipotética (imparfait + conditionnel présent) e a condição irreal no passado (plus-que-parfait + conditionnel passé).

O domínio dessas estruturas é o que diferencia um falante intermediário de um avançado, permitindo expressar nuances de probabilidade.', 'Si + presente -> futuro/presente. Si + imparfait -> conditionnel présent. Si + plus-que-parfait -> conditionnel passé.', '[{"title_pt_br":"Condição real","explanation_pt_br":"Algo possível no futuro.","examples":[{"target":"Si j''ai le temps, je viendrai.","translation_pt_br":"Se eu tiver tempo, eu virei."}]},{"title_pt_br":"Condição hipotética","explanation_pt_br":"Algo improvável ou imaginário.","examples":[{"target":"Si j''étais riche, j''achèterais une maison.","translation_pt_br":"Se eu fosse rico, eu compraria uma casa."}]}]'::jsonb, '[{"incorrect":"Si j''aurais le temps, je viendrais.","correct":"Si j''avais le temps, je viendrais.","explanation_pt_br":"Nunca se usa o condicional após ''si'' na oração condicional."},{"incorrect":"Si je serais riche...","correct":"Si j''étais riche...","explanation_pt_br":"O verbo ''etre'' deve estar no imparfait após ''si''."},{"incorrect":"Si j''ai su, j''aurais fait.","correct":"Si j''avais su, j''aurais fait.","explanation_pt_br":"Para o passado, usa-se o plus-que-parfait após ''si''."}]'::jsonb, '["O ''si'' nunca é seguido pelo condicional ou futuro.","A ordem das orações pode ser invertida sem mudar o sentido."]'::jsonb, 9),
('fr-grammar-B2-10', 'fr', 'B2', 'Discours rapporté et nuance', 'O discurso relatado (discours rapporté) é usado para transmitir o que alguém disse. Quando o verbo introdutório está no passado, os tempos verbais da fala original devem ser ajustados (concordância dos tempos).

Além disso, o uso de conectores e nuances verbais permite que o falante B2 demonstre maior controle sobre a precisão e a polidez, diferenciando fatos de opiniões ou boatos.', 'Verbo introdutório (dire, demander, etc.) + que/si/ce que + oração ajustada. Presente vira imparfait, passé composé vira plus-que-parfait, futur vira conditionnel.', '[{"title_pt_br":"Relatar uma afirmação","explanation_pt_br":"Contar o que alguém disse no passado.","examples":[{"target":"Il a dit qu''il était fatigué.","translation_pt_br":"Ele disse que estava cansado."}]},{"title_pt_br":"Relatar uma pergunta","explanation_pt_br":"Transformar perguntas diretas em indiretas.","examples":[{"target":"Il m''a demandé si je venais.","translation_pt_br":"Ele me perguntou se eu vinha."}]}]'::jsonb, '[{"incorrect":"Il a dit qu''il est fatigué.","correct":"Il a dit qu''il était fatigué.","explanation_pt_br":"Se o verbo principal está no passado, o tempo da subordinada deve ser ajustado."},{"incorrect":"Il m''a demandé qu''est-ce que je fais.","correct":"Il m''a demandé ce que je faisais.","explanation_pt_br":"Em perguntas indiretas, não se usa a estrutura interrogativa direta."},{"incorrect":"Il a dit que je viendrai.","correct":"Il a dit que je viendrais.","explanation_pt_br":"O futuro deve ser transformado em condicional no discurso relatado."}]'::jsonb, '["O uso de ''si'' é obrigatório para perguntas que começam com ''est-ce que''.","Atenção à mudança de pronomes pessoais (eu vira ele/ela)."]'::jsonb, 10),
('it-grammar-A1-1', 'it', 'A1', 'Essere e avere', 'Os verbos essere (ser/estar) e avere (ter) são os pilares da língua italiana. Diferente do português, onde usamos ''ter'' para idade e sensações físicas, o italiano utiliza quase exclusivamente o verbo ''avere''.

Essere é usado para estados permanentes, identidades e localização, enquanto avere é usado para posse e estados fisiológicos. Dominar esses dois verbos é essencial, pois eles também funcionam como auxiliares para a formação de tempos compostos.', 'Essere: io sono, tu sei, lui/lei è, noi siamo, voi siete, loro sono. Avere: io ho, tu hai, lui/lei ha, noi abbiamo, voi avete, loro hanno. A negação é feita colocando ''non'' antes do verbo. A interrogação é feita apenas com a entonação na fala ou ponto de interrogação na escrita.', '[{"title_pt_br":"Identidade e Profissão","explanation_pt_br":"Usamos essere para definir quem somos ou o que fazemos.","examples":[{"target":"Io sono brasiliano.","translation_pt_br":"Eu sou brasileiro."},{"target":"Lui è un professore.","translation_pt_br":"Ele é um professor."}]},{"title_pt_br":"Posse","explanation_pt_br":"Usamos avere para indicar que algo pertence a alguém.","examples":[{"target":"Io ho una macchina rossa.","translation_pt_br":"Eu tenho um carro vermelho."}]},{"title_pt_br":"Idade e Sensações","explanation_pt_br":"Em italiano, a idade e sensações como fome ou sede são expressas com avere.","examples":[{"target":"Quanti anni hai?","translation_pt_br":"Quantos anos você tem?"},{"target":"Ho molta fame.","translation_pt_br":"Estou com muita fome."}]}]'::jsonb, '[{"incorrect":"Sono 20 anni.","correct":"Ho 20 anni.","explanation_pt_br":"Brasileiros tendem a usar o verbo ser para idade, mas em italiano usa-se avere."},{"incorrect":"Ho freddo (para temperatura ambiente).","correct":"Fa freddo.","explanation_pt_br":"Ho freddo é para a pessoa sentir frio; para o clima, usa-se o verbo fare."},{"incorrect":"Io sono fame.","correct":"Ho fame.","explanation_pt_br":"Sensações físicas como fome, sede ou sono usam o verbo avere."}]'::jsonb, '["O ''h'' em ''ho, hai, ha, hanno'' é mudo, serve apenas para distinguir do ''o'' (ou), ''ai'' (aos), ''a'' (a) e ''anno'' (ano).","Em contextos informais, o sujeito (io, tu, lui) é frequentemente omitido."]'::jsonb, 1),
('it-grammar-A1-2', 'it', 'A1', 'Articoli e accordo', 'Os artigos italianos concordam em gênero (masculino/feminino) e número (singular/plural) com o substantivo. Diferente do português, a escolha do artigo depende da letra inicial da palavra seguinte, o que exige atenção especial para evitar cacofonia.

O acordo é rigoroso: adjetivos e artigos devem sempre seguir o substantivo. Se o substantivo muda para o plural, o artigo e o adjetivo devem acompanhá-lo obrigatoriamente.', 'Artigos definidos: il/lo/l'' (masc. sing.), la/l'' (fem. sing.), i/gli (masc. pl.), le (fem. pl.). O uso de ''lo'' e ''gli'' ocorre antes de palavras iniciadas por s+consoante, z, gn, ps, x, y.', '[{"title_pt_br":"Artigos definidos","explanation_pt_br":"Usados para objetos ou pessoas específicas.","examples":[{"target":"Il libro è sul tavolo.","translation_pt_br":"O livro está sobre a mesa."},{"target":"Lo studente è intelligente.","translation_pt_br":"O estudante é inteligente."}]},{"title_pt_br":"Concordância de adjetivos","explanation_pt_br":"O adjetivo deve concordar com o substantivo que qualifica.","examples":[{"target":"Le case sono belle.","translation_pt_br":"As casas são bonitas."}]}]'::jsonb, '[{"incorrect":"Il studente.","correct":"Lo studente.","explanation_pt_br":"Palavras iniciadas por ''s'' seguida de consoante exigem ''lo''."},{"incorrect":"Le amica.","correct":"Le amiche.","explanation_pt_br":"O substantivo também deve ir para o plural, não apenas o artigo."},{"incorrect":"La zaino.","correct":"Lo zaino.","explanation_pt_br":"Zaino começa com ''z'', exigindo o artigo ''lo''."}]'::jsonb, '["A maioria dos substantivos terminados em ''o'' são masculinos e em ''a'' são femininos.","Substantivos terminados em ''e'' podem ser masculinos ou femininos, exigindo memorização."]'::jsonb, 2),
('it-grammar-A2-3', 'it', 'A2', 'Il presente', 'O presente indicativo italiano é usado para ações habituais, verdades universais e, frequentemente, para o futuro próximo. Existem três conjugações principais baseadas na terminação do infinitivo: -are, -ere e -ire.

Embora a estrutura seja regular para a maioria dos verbos, o italiano possui muitos verbos irregulares de alta frequência que devem ser memorizados individualmente.', 'Para -are: -o, -i, -a, -iamo, -ate, -ano. Para -ere: -o, -i, -e, -iamo, -ete, -ono. Para -ire: -o, -i, -e, -iamo, -ite, -ono (alguns verbos em -ire recebem o sufixo -isc- entre a raiz e a terminação).', '[{"title_pt_br":"Ações habituais","explanation_pt_br":"Rotina diária.","examples":[{"target":"Ogni mattina bevo un caffè.","translation_pt_br":"Toda manhã bebo um café."}]},{"title_pt_br":"Verdades universais","explanation_pt_br":"Fatos que não mudam.","examples":[{"target":"La terra gira intorno al sole.","translation_pt_br":"A terra gira em torno do sol."}]}]'::jsonb, '[{"incorrect":"Io mangio la pasta ogni giorno.","correct":"Mangio la pasta ogni giorno.","explanation_pt_br":"Embora não seja um erro gramatical, omitir o pronome ''io'' soa muito mais natural."},{"incorrect":"Loro dormono.","correct":"Loro dormono.","explanation_pt_br":"Brasileiros às vezes confundem a terminação de ''loro'' com a de ''noi''."},{"incorrect":"Io finisco il lavoro.","correct":"Finisco il lavoro.","explanation_pt_br":"Esquecer o infixo -isc- em verbos como ''finire''."}]'::jsonb, '["Verbos como ''andare'', ''fare'', ''stare'' e ''bere'' são altamente irregulares.","A conjugação ''noi'' é quase sempre igual à do português, facilitando a memorização."]'::jsonb, 3),
('it-grammar-A2-4', 'it', 'A2', 'Il passato prossimo', 'O passato prossimo é o tempo verbal mais usado para narrar eventos concluídos no passado. Ele é composto pelo presente do auxiliar (essere ou avere) + o particípio passado do verbo principal.

A escolha entre essere e avere é crucial: verbos de movimento ou mudança de estado usam ''essere'' (com concordância), enquanto verbos transitivos usam ''avere''.', 'Avere/Essere + Particípio (-ato, -uto, -ito). Ex: Ho mangiato, sono andato/a. Se usa essere, o particípio concorda em gênero e número com o sujeito.', '[{"title_pt_br":"Ações pontuais","explanation_pt_br":"Eventos que aconteceram uma vez no passado.","examples":[{"target":"Ieri ho comprato un libro.","translation_pt_br":"Ontem comprei um livro."}]},{"title_pt_br":"Mudança de estado","explanation_pt_br":"Eventos que envolvem movimento ou mudança.","examples":[{"target":"Sono andato a Roma.","translation_pt_br":"Fui a Roma."}]}]'::jsonb, '[{"incorrect":"Ho andato a casa.","correct":"Sono andato a casa.","explanation_pt_br":"Verbos de movimento exigem o auxiliar ''essere''."},{"incorrect":"Lei è mangiato.","correct":"Lei ha mangiato.","explanation_pt_br":"Verbos transitivos (que pedem objeto direto) usam ''avere''."},{"incorrect":"Sono andata (falado por um homem).","correct":"Sono andato.","explanation_pt_br":"O particípio com ''essere'' deve concordar com o gênero do sujeito."}]'::jsonb, '["Muitos verbos têm particípios irregulares, como ''fatto'' (fare), ''detto'' (dire), ''scritto'' (scrivere).","O ''passato prossimo'' é usado para ações que têm impacto no presente."]'::jsonb, 4),
('it-grammar-A2-5', 'it', 'A2', 'Futuro e progetti', 'O futuro simples é usado para intenções, previsões e promessas. Em italiano, o futuro é formado por uma única palavra, ao contrário do português que usa ''vou fazer''.

Embora exista o futuro composto, o nível A2 foca no futuro simples. É comum usar o presente para planos imediatos, mas o futuro simples é necessário para planos a médio e longo prazo.', 'Raiz do verbo + terminações: -ò, -ai, -à, -emo, -ete, -anno. Verbos em -are mudam o ''a'' da raiz para ''e'' (ex: parlare -> parlerò).', '[{"title_pt_br":"Previsões","explanation_pt_br":"Falar sobre o que acontecerá.","examples":[{"target":"Domani pioverà.","translation_pt_br":"Amanhã choverá."}]},{"title_pt_br":"Planos futuros","explanation_pt_br":"Intenções para o futuro.","examples":[{"target":"L''anno prossimo andrò in Italia.","translation_pt_br":"Ano que vem irei para a Itália."}]}]'::jsonb, '[{"incorrect":"Vado a studiare domani.","correct":"Studierò domani.","explanation_pt_br":"Embora o presente seja aceito, o futuro simples é mais preciso para planos distantes."},{"incorrect":"Io parlarò.","correct":"Parlerò.","explanation_pt_br":"Verbos em -are mudam o ''a'' da raiz para ''e'' no futuro."},{"incorrect":"Lui andrà.","correct":"Lui andrà.","explanation_pt_br":"Erro comum é esquecer o acento gráfico na terceira pessoa do singular."}]'::jsonb, '["O futuro simples também pode ser usado para expressar dúvida ou suposição no presente.","Muitos verbos irregulares no futuro perdem a vogal da raiz (ex: andare -> andrò)."]'::jsonb, 5),
('it-grammar-B1-6', 'it', 'B1', 'Imperfetto o passato prossimo', 'A escolha entre imperfetto e passato prossimo é um dos maiores desafios para brasileiros. O passato prossimo foca na conclusão da ação (o ''quê''), enquanto o imperfetto foca na duração, hábito ou descrição no passado (o ''como'' ou ''quando'').

Imagine o imperfetto como o cenário de um filme e o passato prossimo como as ações que acontecem dentro desse cenário.', 'Imperfetto: -avo, -avi, -ava, -avamo, -avate, -avano (para -are); -evo, -evi, -eva, -evamo, -evate, -evano (para -ere); -ivo, -ivi, -iva, -ivamo, -ivate, -ivano (para -ire).', '[{"title_pt_br":"Hábitos no passado","explanation_pt_br":"Ações que se repetiam.","examples":[{"target":"Da bambino giocavo sempre al parco.","translation_pt_br":"Quando criança, eu sempre brincava no parque."}]},{"title_pt_br":"Descrição de estados","explanation_pt_br":"Descrever o clima ou sentimentos.","examples":[{"target":"Faceva caldo e io ero stanco.","translation_pt_br":"Estava calor e eu estava cansado."}]}]'::jsonb, '[{"incorrect":"Ieri ho mangiato mentre guardavo la TV.","correct":"Ieri mangiavo mentre guardavo la TV.","explanation_pt_br":"Se duas ações são simultâneas e duradouras, ambas devem estar no imperfetto."},{"incorrect":"Quando sono arrivato, lei ha dormito.","correct":"Quando sono arrivato, lei dormiva.","explanation_pt_br":"A ação que serve de pano de fundo deve estar no imperfetto."},{"incorrect":"Ho avuto 10 anni.","correct":"Avevo 10 anni.","explanation_pt_br":"Idade no passado é sempre imperfetto."}]'::jsonb, '["O verbo ''essere'' no imperfetto é ''ero, eri, era, eravamo, eravate, erano''.","O imperfetto é o tempo da memória e da nostalgia."]'::jsonb, 6),
('it-grammar-B1-7', 'it', 'B1', 'Pronomi combinati', 'Os pronomes combinados ocorrem quando usamos dois pronomes (objeto indireto + objeto direto) na mesma frase. Em italiano, eles se fundem em uma única palavra (ex: ''mi'' + ''lo'' = ''melo'').

Esta é uma estrutura complexa que exige que o aluno identifique corretamente o complemento direto e o indireto antes de realizar a combinação.', 'Os pronomes indiretos (mi, ti, gli, ci, vi) mudam a vogal final para ''e'' antes de lo, la, li, le. Ex: mi + lo = melo; gli + lo = glielo.', '[{"title_pt_br":"Dar algo a alguém","explanation_pt_br":"Substituir o objeto e o destinatário.","examples":[{"target":"Mi dai il libro? Sì, te lo do.","translation_pt_br":"Você me dá o livro? Sim, eu te dou (ele)."}]},{"title_pt_br":"Explicar algo a alguém","explanation_pt_br":"Uso de glielo para ele/ela.","examples":[{"target":"Ho spiegato il problema a Marco. Gliel''ho spiegato.","translation_pt_br":"Expliquei o problema a Marco. Eu o expliquei a ele."}]}]'::jsonb, '[{"incorrect":"Mi lo dai?","correct":"Me lo dai?","explanation_pt_br":"A combinação correta de ''mi'' + ''lo'' é ''me lo''."},{"incorrect":"Gli lo dico.","correct":"Glielo dico.","explanation_pt_br":"A combinação de ''gli'' + ''lo'' resulta em ''glielo''."},{"incorrect":"Lo mi dai?","correct":"Me lo dai?","explanation_pt_br":"A ordem correta é sempre pronome indireto antes do direto."}]'::jsonb, '["O ''glielo'' é usado tanto para ''a lui'' quanto para ''a lei''.","Com tempos compostos, o particípio deve concordar com o pronome direto (ex: Gliel''ho data - a caneta)."]'::jsonb, 7),
('it-grammar-B1-8', 'it', 'B1', 'Il congiuntivo', 'O congiuntivo é o modo da subjetividade, da dúvida, da opinião e do desejo. Diferente do indicativo, que trata de fatos, o congiuntivo é usado após verbos que expressam incerteza ou emoção.

Para brasileiros, é um desafio, pois o uso do subjuntivo no português falado é cada vez mais raro, enquanto no italiano é obrigatório após certas conjunções e verbos.', 'Presente: -are (-i, -i, -i, -iamo, -iate, -ino); -ere/-ire (-a, -a, -a, -iamo, -iate, -ano).', '[{"title_pt_br":"Expressar opinião","explanation_pt_br":"Após verbos como ''pensare'' ou ''credere''.","examples":[{"target":"Penso che sia una buona idea.","translation_pt_br":"Penso que seja uma boa ideia."}]},{"title_pt_br":"Expressar desejo","explanation_pt_br":"Após verbos como ''volere'' ou ''sperare''.","examples":[{"target":"Voglio che tu venga con me.","translation_pt_br":"Quero que você venha comigo."}]}]'::jsonb, '[{"incorrect":"Penso che è vero.","correct":"Penso che sia vero.","explanation_pt_br":"Após ''penso che'', o uso do congiuntivo é obrigatório."},{"incorrect":"Spero che lui viene.","correct":"Spero che lui venga.","explanation_pt_br":"Verbos de desejo exigem o congiuntivo."},{"incorrect":"Credo che abbiamo ragione.","correct":"Credo che abbiamo ragione.","explanation_pt_br":"Embora a forma esteja correta, o erro comum é usar o indicativo por influência do português informal."}]'::jsonb, '["O congiuntivo é frequentemente introduzido pela conjunção ''che''.","A escolha do tempo do congiuntivo depende do tempo do verbo principal."]'::jsonb, 8),
('it-grammar-B2-9', 'it', 'B2', 'Periodo ipotetico', 'O período hipotético (frases condicionais) expressa uma condição e sua consequência. Existem três tipos principais: real (possível), possível (improvável) e irreal (impossível no passado).

O domínio do período hipotético marca a transição para a fluência, permitindo discussões complexas sobre hipóteses e cenários teóricos.', 'Tipo 1 (Real): Se + presente, presente/futuro. Tipo 2 (Possível): Se + congiuntivo imperfetto, condizionale presente. Tipo 3 (Irreal): Se + congiuntivo trapassato, condizionale passato.', '[{"title_pt_br":"Condição real","explanation_pt_br":"Se algo acontecer, algo acontecerá.","examples":[{"target":"Se ho tempo, vado al cinema.","translation_pt_br":"Se eu tiver tempo, vou ao cinema."}]},{"title_pt_br":"Condição irreal","explanation_pt_br":"Hipótese impossível no presente.","examples":[{"target":"Se avessi soldi, comprerei una casa.","translation_pt_br":"Se eu tivesse dinheiro, compraria uma casa."}]}]'::jsonb, '[{"incorrect":"Se avrei soldi, comprerei.","correct":"Se avessi soldi, comprerei.","explanation_pt_br":"Nunca se usa o condicional após o ''se'' na frase hipotética."},{"incorrect":"Se ho avuto tempo, andavo.","correct":"Se avessi avuto tempo, sarei andato.","explanation_pt_br":"Para o passado irreal, deve-se usar o congiuntivo trapassato e o condizionale passato."},{"incorrect":"Se vado, comprerò.","correct":"Se vado, comprerò.","explanation_pt_br":"Embora gramaticalmente possível, o uso do futuro na prótase (após o se) é um erro comum de registro."}]'::jsonb, '["O ''se'' nunca aceita o condicional diretamente.","O período hipotético é a estrutura mais refinada para argumentação em italiano."]'::jsonb, 9),
('it-grammar-B2-10', 'it', 'B2', 'Discorso indiretto e sfumature', 'O discurso indireto é usado para relatar o que alguém disse. Em italiano, isso exige a concordância dos tempos verbais (correlazione dei tempi). Se o verbo introdutório está no passado, o tempo da fala original deve ser ajustado para trás.

Além disso, o nível B2 exige o uso de nuances modais, como o uso do condicional para suavizar pedidos ou expressar incerteza.', 'Se o verbo principal está no passado: presente vira imperfetto, passato prossimo vira trapassato prossimo, futuro vira condizionale passato.', '[{"title_pt_br":"Relatar falas","explanation_pt_br":"Transformar fala direta em indireta.","examples":[{"target":"Lui ha detto: ''Vado a casa''. -> Lui ha detto che andava a casa.","translation_pt_br":"Ele disse: ''Vou para casa''. -> Ele disse que ia para casa."}]},{"title_pt_br":"Suavização","explanation_pt_br":"Usar o condicional para ser educado.","examples":[{"target":"Vorrei un caffè, per favore.","translation_pt_br":"Eu gostaria de um café, por favor."}]}]'::jsonb, '[{"incorrect":"Ha detto che va a casa.","correct":"Ha detto che andava a casa.","explanation_pt_br":"Após um verbo no passado, o tempo da oração subordinada deve ser recuado."},{"incorrect":"Voglio un caffè.","correct":"Vorrei un caffè.","explanation_pt_br":"O uso do indicativo presente para pedidos soa rude; o condicional é a forma padrão de polidez."},{"incorrect":"Mi ha chiesto cosa faccio.","correct":"Mi ha chiesto cosa facessi.","explanation_pt_br":"Em perguntas indiretas no passado, usa-se o congiuntivo imperfetto."}]'::jsonb, '["O uso do condicional ''vorrei'' é essencial para não parecer autoritário.","A concordância de tempos é o que diferencia um falante B2 de um iniciante."]'::jsonb, 10)
on conflict (id) do update set
  language = excluded.language,
  level = excluded.level,
  title = excluded.title,
  overview_pt_br = excluded.overview_pt_br,
  formation_pt_br = excluded.formation_pt_br,
  use_cases = excluded.use_cases,
  common_mistakes = excluded.common_mistakes,
  notes_pt_br = excluded.notes_pt_br,
  sort_order = excluded.sort_order,
  is_published = true;

update public.grammar_exercises as exercise
set topic_id = topic.id
from public.grammar_topics as topic
where exercise.id like topic.id || '-%';

alter table public.grammar_exercises
  alter column topic_id set not null,
  add constraint grammar_exercises_topic_id_fkey
    foreign key (topic_id) references public.grammar_topics (id) on delete cascade;
